   415  Variant_clear(UA_Variant *p, const UA_DataType *_) {
   416      if(p->storageType != UA_VARIANT_DATA)
   417          return;
   418      if(p->type && p->data > UA_EMPTY_ARRAY_SENTINEL) {
   419          if(p->arrayLength == 0)
